float UMovementComponent::SlideAlongSurface(const FVector& Delta, float Time, const FVector& Normal, FHitResult& Hit, bool bHandleImpact)
{
	if (!Hit.bBlockingHit)
	{
		return 0.f;
	}

	float PercentTimeApplied = 0.f;
	const FVector OldHitNormal = Normal;

	FVector SlideDelta = ComputeSlideVector(Delta, Time, Normal, Hit);

	if ((SlideDelta | Delta) > 0.f)
	{
		const FQuat Rotation = UpdatedComponent->GetComponentQuat();
		SafeMoveUpdatedComponent(SlideDelta, Rotation, true, Hit);

		const float FirstHitPercent = Hit.Time;
		PercentTimeApplied = FirstHitPercent;
		if (Hit.IsValidBlockingHit())
		{
			// Notify first impact
			if (bHandleImpact)
			{
				HandleImpact(Hit, FirstHitPercent * Time, SlideDelta);
			}

			// Compute new slide normal when hitting multiple surfaces.
			TwoWallAdjust(SlideDelta, Hit, OldHitNormal);

			// Only proceed if the new direction is of significant length and not in reverse of original attempted move.
			if (!SlideDelta.IsNearlyZero(1e-3f) && (SlideDelta | Delta) > 0.f)
			{
				// Perform second move
				SafeMoveUpdatedComponent(SlideDelta, Rotation, true, Hit);
				const float SecondHitPercent = Hit.Time * (1.f - FirstHitPercent);
				PercentTimeApplied += SecondHitPercent;

				// Notify second impact
				if (bHandleImpact && Hit.bBlockingHit)
				{
					HandleImpact(Hit, SecondHitPercent * Time, SlideDelta);
				}
			}
		}

		return FMath::Clamp(PercentTimeApplied, 0.f, 1.f);
	}

	return 0.f;
}

		PercentTimeApplied = FMath::Clamp(PercentTimeApplied + SecondHitPercent, 0.f, 1.f);
	}

	if (Hit.IsValidBlockingHit())
	{
		const FMovementBaseInterfaceData* MovementBaseData = GetMovementBaseInterfaceData();
		const UObject* MovementBaseObject = MovementBaseData ? GetMovementBaseInterfaceData()->PhysicsObjectOwner.Get() : nullptr;
		if (CanStepUp(Hit) || 
			(Hit.PhysicsObjectOwner.Get() == MovementBaseObject) || 
			(Hit.Component.Get() == MovementBaseObject))
		{
			// hit a barrier, try to step up
			const FVector PreStepUpLocation = UpdatedComponent->GetComponentLocation();
			if (!StepUp(GetGravityDirection(), Delta * (1.f - PercentTimeApplied), Hit, OutStepDownResult))
			{
				UE_LOGF(LogCharacterMovement, Verbose, "- StepUp (ImpactNormal %ls, Normal %ls", *Hit.ImpactNormal.ToString(), *Hit.Normal.ToString());
				HandleImpact(Hit, LastMoveTimeSlice, RampVector);
				SlideAlongSurface(Delta, 1.f - PercentTimeApplied, Hit.Normal, Hit, true);
			}
			else
			{
				UE_LOGF(LogCharacterMovement, Verbose, "+ StepUp (ImpactNormal %ls, Normal %ls", *Hit.ImpactNormal.ToString(), *Hit.Normal.ToString());
				if (!bMaintainHorizontalGroundVelocity)
				{
					// Don't recalculate velocity based on this height adjustment, if considering vertical adjustments. Only consider horizontal movement.
					bJustTeleported = true;
					const float StepUpTimeSlice = (1.f - PercentTimeApplied) * DeltaSeconds;
					if (!HasAnimRootMotion() && !CurrentRootMotion.HasOverrideVelocity() && StepUpTimeSlice >= UE_KINDA_SMALL_NUMBER)
					{
						Velocity = (UpdatedComponent->GetComponentLocation() - PreStepUpLocation) / StepUpTimeSlice;
						Velocity = ProjectToGravityFloor(Velocity);
					}
				}
			}
		}
		else if ( Hit.Component.IsValid() && !Hit.Component.Get()->CanCharacterStepUp(CharacterOwner) )
		{
			HandleImpact(Hit, LastMoveTimeSlice, RampVector);
			SlideAlongSurface(Delta, 1.f - PercentTimeApplied, Hit.Normal, Hit, true);
		}
	}
}

// step fwd
FHitResult Hit(1.f);
MoveUpdatedComponent( Delta, PawnRotation, true, &Hit);

// Check result of forward movement
if (Hit.bBlockingHit)
{
	if (Hit.bStartPenetrating)
	{
		// Undo movement
		ScopedStepUpMovement.RevertMove();
		return false;
	}

	// If we hit something above us and also something ahead of us, we should notify about the upward hit as well.
	// The forward hit will be handled later (in the bSteppedOver case below).
	// In the case of hitting something above but not forward, we are not blocked from moving so we don't need the notification.
	if (SweepUpHit.bBlockingHit && Hit.bBlockingHit)
	{
		HandleImpact(SweepUpHit);
	}

	// pawn ran into a wall
	HandleImpact(Hit);
	if (IsFalling())
	{
		return true;
	}

	// adjust and try again
	const float ForwardHitTime = Hit.Time;
	const float ForwardSlideAmount = SlideAlongSurface(Delta, 1.f - Hit.Time, Hit.Normal, Hit, true);

	if (IsFalling())
	{
		ScopedStepUpMovement.RevertMove();
		return false;
	}

